import { Injectable, OnDestroy } from '@angular/core';
import { Observable, Subject } from 'rxjs';
import { broadCastBody } from '../../interfaces/login.interface';
import { ErrorHandlerUtil } from '../../../userpanel/utility/error-handler.util';
import { BROADCAST_EVENTS } from '../../../userpanel/utility/user-panel-constants';

@Injectable({
  providedIn: 'root'
})
export class BroadcastingService implements OnDestroy {
  private static readonly CHANNEL_NAME = 'etabella-mipl';

  private readonly channel?: BroadcastChannel;

  private readonly authSubject = new Subject<broadCastBody>();
  private readonly individualMultipleTabSubject = new Subject<broadCastBody>();
  private readonly individualTabOpenSubject = new Subject<broadCastBody>();
  private readonly individualOpenExistsSubject = new Subject<broadCastBody>();
  private readonly presentationExistsSubject = new Subject<broadCastBody>();
  private readonly searchChangesSubject = new Subject<broadCastBody>();
  private readonly searchDeactivateSubject = new Subject<broadCastBody>();
  private readonly factSheetOpenSubject = new Subject<broadCastBody>();
  private readonly factSheetDeleteSubject = new Subject<broadCastBody>();
  private readonly fileListReloadSubject = new Subject<broadCastBody>();

  public readonly tabId = BroadcastingService.createTabId();

  constructor() {
    if (typeof BroadcastChannel === 'undefined') {
      return;
    }

    try {
      this.channel = new BroadcastChannel(BroadcastingService.CHANNEL_NAME);
      this.channel.onmessage = (e: MessageEvent) => {
        const data = e?.data as broadCastBody | undefined;
        if (!data || data.tabId === this.tabId) {
          return;
        }

        switch (data.event) {
          case BROADCAST_EVENTS.LOG_IN_ANOTHER_BROWSER:
          case BROADCAST_EVENTS.LOGIN:
          case BROADCAST_EVENTS.LOGGED_OUT:
            this.authSubject.next(data);
            break;

          case BROADCAST_EVENTS.INDIVIDUAL_MULTIPLE_TAB:
            this.individualMultipleTabSubject.next(data);
            break;

          case BROADCAST_EVENTS.INDIVIDUAL_OPEN_TAB:
            this.individualTabOpenSubject.next(data);
            break;

          case BROADCAST_EVENTS.INDIVIDUAL_OPEN:
            this.individualOpenExistsSubject.next(data);
            break;

          case BROADCAST_EVENTS.PRESENTATION_END:
            this.presentationExistsSubject.next(data);
            break;

          case BROADCAST_EVENTS.SEARCH_CHANGED:
            this.searchChangesSubject.next(data);
            break;

          case BROADCAST_EVENTS.DEACTIVATE_SEARCH:
            this.searchDeactivateSubject.next(data);
            break;

          case BROADCAST_EVENTS.INDIVIDUAL_FACT_SHEET_OPEN:
            this.factSheetOpenSubject.next(data);
            break;

          case BROADCAST_EVENTS.INDIVIDUAL_FACT_SHEET_DELETE:
            this.factSheetDeleteSubject.next(data);
            break;

          case BROADCAST_EVENTS.RELOAD_FILE_LIST:
            this.fileListReloadSubject.next(data);
            break;

          default:
            break;
        }
      };
    } catch (error) {
      throw new Error(`BroadcastChannel initialization failed: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }

  public authListener(): Observable<broadCastBody> {
    return this.authSubject.asObservable();
  }

  public indiMultiTabListener(): Observable<broadCastBody> {
    return this.individualMultipleTabSubject.asObservable();
  }

  public indiTabOpenListener(): Observable<broadCastBody> {
    return this.individualTabOpenSubject.asObservable();
  }

  public indiOpenExistsListener(): Observable<broadCastBody> {
    return this.individualOpenExistsSubject.asObservable();
  }

  public presentationExistsListener(): Observable<broadCastBody> {
    return this.presentationExistsSubject.asObservable();
  }

  public onSearchChange(): Observable<broadCastBody> {
    return this.searchChangesSubject.asObservable();
  }

  public onSearchDeactivate(): Observable<broadCastBody> {
    return this.searchDeactivateSubject.asObservable();
  }

  public factSheetOpenListener(): Observable<broadCastBody> {
    return this.factSheetOpenSubject.asObservable();
  }

  public factSheetDeleteListener(): Observable<broadCastBody> {
    return this.factSheetDeleteSubject.asObservable();
  }

  public fileListReloadListener(): Observable<broadCastBody> {
    return this.fileListReloadSubject.asObservable();
  }

  // POSTING BROADCASTING
  public portMessage(body: broadCastBody): void {
    if (!this.channel) {
      return;
    }

    try {
      const message: broadCastBody = { ...body, tabId: this.tabId };
      this.channel.postMessage(message);
    } catch (error) {
      throw new Error(`BroadcastChannel postMessage failed: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }

  public ngOnDestroy(): void {
    try {
      this.channel?.close();
    } catch (error) {
      throw new Error(`BroadcastChannel close failed: ${ErrorHandlerUtil.getErrorMessage(error)}`);
    }
  }

  private static createTabId(): string {
    const cryptoObj = globalThis.crypto as Crypto | undefined;
    if (cryptoObj?.randomUUID) {
      return cryptoObj.randomUUID();
    }
    return `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  }
}
